import numpy as np
import numba

text1 = "gen = np.random.default_rng(0); @numba.jit def foo(gen): return gen.binomial(301, 0.1, 3); foo(gen)"
try:
    gen = np.random.default_rng(0)

    @numba.jit
    def foo(gen):
        return gen.binomial(301, 0.1, 3)

    value1 = foo(gen)
except Exception as e:
    probe_exception(text1, e)
else:
    probe(text1, value1)

